metrics=json.loads((R.parent/'agreement.json').read_text())
sections=[]; structured=[]
for d in metrics[:25]:
 rank=d['rank'];gate,evidence,integrity=notes[rank]
 a,b=d['a'],d['b'];n=d['native'];v=d['packet_variant']
 def span(start,count):return f'{start}..{start+count-1}' if count else 'none'
 agreement=f"Offsets: {a}={d['offset_a']}, {b}={d['offset_b']}; displayed lengths {d['length_a']} and {d['length_b']}. At equal native indices, the initial agreement is {n['count']} terms"
 agreement+=f" (n={span(n['a_start'],n['count'])})" if n['count'] else ''
 if 'mismatch' in n:
  m=n['mismatch'];agreement+=f"; the next comparison at n={m['a_index']} is {m['a']} versus {m['b']}"
 else:agreement+='; this count is limited by the shorter displayed list'
 agreement+='.'
 if d['variant']!='raw':agreement+=f" Packet `{d['variant']}` agreement: {v['count']} terms, comparing indices {span(v['a_start'],v['count'])} and {span(v['b_start'],v['count'])}"+(' after taking absolute values.' if v['absolute'] else '.')
 entry=f"## Candidate {rank}: {a} vs {b}\n\n**DROP — {gate}.**\n\n**Agreement and offsets.** {agreement}\n\n**Evidence.** {evidence}\n\n**Novelty and integrity.** {integrity}\n\nSources: [{a}](https://oeis.org/{a}), [{b}](https://oeis.org/{b}); freshly retrieved [first record](records/{a}.seq) and [second record](records/{b}.seq).\n"
 # Final report is one level above evidence; source links fixed during assembly.
 sections.append(entry)
 structured.append(dict(rank=rank,a=a,b=b,verdict='DROP',primary_gate=gate,agreement=agreement,evidence=evidence,novelty_integrity=integrity))
(R/'61-85.md').write_text('\n'.join(sections))
(R/'61-85.json').write_text(json.dumps(structured,indent=2))
print('wrote',len(sections),'sections')
